import java.math.BigDecimal;

/**
 * FeeCalculator 的独立测试类，使用 main 方法与断言。
 */
public class FeeCalculatorTest {

    private static final FeeCalculator CALCULATOR = new FeeCalculator();

    public static void main(String[] args) {
        testDeliveryFee();
        testServiceFee();
        testInputNotModified();
        System.out.println("所有测试通过");
    }

    private static void testDeliveryFee() {
        // 件数为 0
        assertEquals("deliveryFee(0, 0)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("0"), 0));
        assertEquals("deliveryFee(100, 0)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("100"), 0));
        assertEquals("deliveryFee(200, 0)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("200"), 0));
        assertEquals("deliveryFee(200.01, 0)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("200.01"), 0));

        // 件数 > 0，金额 <= 200
        assertEquals("deliveryFee(0, 1)", "12.00", CALCULATOR.deliveryFee(new BigDecimal("0"), 1));
        assertEquals("deliveryFee(100, 1)", "12.00", CALCULATOR.deliveryFee(new BigDecimal("100"), 1));
        assertEquals("deliveryFee(199.99, 1)", "12.00", CALCULATOR.deliveryFee(new BigDecimal("199.99"), 1));
        assertEquals("deliveryFee(200, 1)", "12.00", CALCULATOR.deliveryFee(new BigDecimal("200"), 1));

        // 件数 > 0，金额严格大于 200
        assertEquals("deliveryFee(200.01, 1)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("200.01"), 1));
        assertEquals("deliveryFee(300, 1)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("300"), 1));
        assertEquals("deliveryFee(200.01, 5)", "0.00", CALCULATOR.deliveryFee(new BigDecimal("200.01"), 5));

        // 异常：金额 null
        assertThrows("deliveryFee(null, 1)", () -> CALCULATOR.deliveryFee(null, 1));
        // 异常：金额负数
        assertThrows("deliveryFee(-0.01, 1)", () -> CALCULATOR.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("deliveryFee(-100, 1)", () -> CALCULATOR.deliveryFee(new BigDecimal("-100"), 1));
        // 异常：件数负数
        assertThrows("deliveryFee(100, -1)", () -> CALCULATOR.deliveryFee(new BigDecimal("100"), -1));
        assertThrows("deliveryFee(0, -1)", () -> CALCULATOR.deliveryFee(new BigDecimal("0"), -1));
    }

    private static void testServiceFee() {
        // 金额为 0
        assertEquals("serviceFee(0)", "0.00", CALCULATOR.serviceFee(new BigDecimal("0")));

        // 0 < 金额 <= 100
        assertEquals("serviceFee(0.01)", "2.00", CALCULATOR.serviceFee(new BigDecimal("0.01")));
        assertEquals("serviceFee(50)", "2.00", CALCULATOR.serviceFee(new BigDecimal("50")));
        assertEquals("serviceFee(99.99)", "2.00", CALCULATOR.serviceFee(new BigDecimal("99.99")));
        assertEquals("serviceFee(100)", "2.00", CALCULATOR.serviceFee(new BigDecimal("100")));

        // 金额严格大于 100
        assertEquals("serviceFee(100.01)", "5.00", CALCULATOR.serviceFee(new BigDecimal("100.01")));
        assertEquals("serviceFee(200)", "5.00", CALCULATOR.serviceFee(new BigDecimal("200")));
        assertEquals("serviceFee(300)", "5.00", CALCULATOR.serviceFee(new BigDecimal("300")));

        // 异常：金额 null
        assertThrows("serviceFee(null)", () -> CALCULATOR.serviceFee(null));
        // 异常：金额负数
        assertThrows("serviceFee(-0.01)", () -> CALCULATOR.serviceFee(new BigDecimal("-0.01")));
        assertThrows("serviceFee(-100)", () -> CALCULATOR.serviceFee(new BigDecimal("-100")));
    }

    private static void testInputNotModified() {
        BigDecimal amount = new BigDecimal("200.01");
        BigDecimal original = new BigDecimal("200.01");
        CALCULATOR.deliveryFee(amount, 1);
        CALCULATOR.serviceFee(amount);
        assertEquals("输入未被修改", original.toPlainString(), amount.toPlainString());

        BigDecimal zero = new BigDecimal("0");
        CALCULATOR.deliveryFee(zero, 0);
        CALCULATOR.serviceFee(zero);
        assertEquals("零输入未被修改", "0", zero.toPlainString());
    }

    private static void assertEquals(String caseName, String expected, BigDecimal actual) {
        if (actual == null) {
            throw new AssertionError(caseName + " 期望 " + expected + "，实际为 null");
        }
        String actualStr = actual.toPlainString();
        if (!expected.equals(actualStr)) {
            throw new AssertionError(caseName + " 期望 " + expected + "，实际 " + actualStr);
        }
    }

    private static void assertThrows(String caseName, Runnable action) {
        try {
            action.run();
        } catch (IllegalArgumentException e) {
            return;
        } catch (Exception e) {
            throw new AssertionError(caseName + " 期望 IllegalArgumentException，实际抛出 " + e.getClass().getName());
        }
        throw new AssertionError(caseName + " 期望 IllegalArgumentException，但未抛出异常");
    }
}
